//

pub trait HeartbeatServiceSyncHandler {
  fn handle_heartbeat(&self, master_info: TMasterInfo) -> thrift::Result<THeartbeatResult>;
}

pub struct HeartbeatServiceSyncProcessor<H: HeartbeatServiceSyncHandler> {
  pub handler: H,
}

impl <H: HeartbeatServiceSyncHandler> HeartbeatServiceSyncProcessor<H> {
  pub fn new(handler: H) -> HeartbeatServiceSyncProcessor<H> {
    HeartbeatServiceSyncProcessor {
      handler,
    }
  }
  fn process_heartbeat(&self, incoming_sequence_number: i32, i_prot: &mut dyn TInputProtocol, o_prot: &mut dyn TOutputProtocol) -> thrift::Result<()> {
    THeartbeatServiceProcessFunctions::process_heartbeat(&self.handler, incoming_sequence_number, i_prot, o_prot)
  }
}

pub struct THeartbeatServiceProcessFunctions;

impl THeartbeatServiceProcessFunctions {
  pub fn process_heartbeat<H: HeartbeatServiceSyncHandler>(handler: &H, incoming_sequence_number: i32, i_prot: &mut dyn TInputProtocol, o_prot: &mut dyn TOutputProtocol) -> thrift::Result<()> {
    let args = HeartbeatServiceHeartbeatArgs::read_from_in_protocol(i_prot)?;
    match handler.handle_heartbeat(args.master_info) {
      Ok(handler_return) => {
        let message_ident = TMessageIdentifier::new("heartbeat", TMessageType::Reply, incoming_sequence_number);
        o_prot.write_message_begin(&message_ident)?;
        let ret = HeartbeatServiceHeartbeatResult { result_value: Some(handler_return) };
        ret.write_to_out_protocol(o_prot)?;
        o_prot.write_message_end()?;
        o_prot.flush()
      },
      Err(e) => {
        match e {
          thrift::Error::Application(app_err) => {
            let message_ident = TMessageIdentifier::new("heartbeat", TMessageType::Exception, incoming_sequence_number);
            o_prot.write_message_begin(&message_ident)?;
            thrift::Error::write_application_error_to_out_protocol(&app_err, o_prot)?;
            o_prot.write_message_end()?;
            o_prot.flush()
          },
          _ => {
            let ret_err = {
              ApplicationError::new(
                ApplicationErrorKind::Unknown,
                e.to_string()
              )
            };
            let message_ident = TMessageIdentifier::new("heartbeat", TMessageType::Exception, incoming_sequence_number);
            o_prot.write_message_begin(&message_ident)?;
            thrift::Error::write_application_error_to_out_protocol(&ret_err, o_prot)?;
            o_prot.write_message_end()?;
            o_prot.flush()
          },
        }
      },
    }
  }
}

impl <H: HeartbeatServiceSyncHandler> TProcessor for HeartbeatServiceSyncProcessor<H> {
  fn process(&self, i_prot: &mut dyn TInputProtocol, o_prot: &mut dyn TOutputProtocol) -> thrift::Result<()> {
    let message_ident = i_prot.read_message_begin()?;
    let res = match &*message_ident.name {
      "heartbeat" => {
        self.process_heartbeat(message_ident.sequence_number, i_prot, o_prot)
      },
      method => {
        Err(
          thrift::Error::Application(
            ApplicationError::new(
              ApplicationErrorKind::UnknownMethod,
              format!("unknown method {}", method)
            )
          )
        )
      },
    };
    thrift::server::handle_process_result(&message_ident, res, o_prot)
  }
}

